using System;
using System.IO;
using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
namespace CampaignDemo.Editor
{
    public static class ForestVerification
    {
        static bool done;static int checks;static double start;
        [InitializeOnLoadMethod]static void Resume(){if(SessionState.GetBool("ForestVerify",false)){start=EditorApplication.timeSinceStartup;EditorApplication.update+=Update;Application.logMessageReceived+=Log;}}
        public static void Run(){EditorSceneManager.OpenScene("Assets/Scenes/Battle01.unity");SessionState.SetBool("ForestVerify",true);start=EditorApplication.timeSinceStartup;EditorApplication.update+=Update;Application.logMessageReceived+=Log;EditorApplication.EnterPlaymode();}
        static void Log(string m,string trace,LogType type){if(type==LogType.Error||type==LogType.Exception){File.WriteAllText("forest-verification-error.txt",m+"\n"+trace);SessionState.SetBool("ForestVerify",false);EditorApplication.Exit(1);}}
        static void Check(bool value,string label){checks++;if(!value)throw new Exception("Forest verification: "+label);Debug.Log("FOREST_CHECK "+label);}
        static BattleUnit Unit(Transform root,string owner,Vector3 position,ArmyCombatDefinition combat)
        {var g=new GameObject(owner);g.transform.SetParent(root);g.transform.position=position;var u=g.AddComponent<BattleUnit>();u.ownerId=owner;u.unitId=owner;u.combatDefinition=combat;var r=g.AddComponent<SpriteRenderer>();return u;}
        static void Update(){if(done)return;if(EditorApplication.timeSinceStartup-start>100){Debug.LogError("Forest verification timeout");return;}if(!EditorApplication.isPlaying||Time.time<.7f)return;done=true;try{Tests();Debug.Log("FOREST_VERIFY_PASS: "+checks+" assertions");File.WriteAllText("forest-verification-result.txt",checks+" assertions passed");SessionState.SetBool("ForestVerify",false);EditorApplication.Exit(0);}catch(Exception e){Debug.LogException(e);}}
        static void Tests()
        {
            var scene=UnityEngine.Object.FindObjectOfType<BattleWorld>();Check(scene!=null&&scene.Initialized,"scene initialized");Check(scene.InForest(scene.units[0]),"editable test forest placed on existing scene");
            var root=new GameObject("Forest isolated tests");var setup=root.AddComponent<RoadMarchSceneSetup>();setup.enabled=false;setup.modes=root.AddComponent<MouseModeStateMachine>();setup.modes.SetMode(MouseCommandMode.Interaction);
            var map=root.AddComponent<FreeMarchMapRuntime>();var data=ScriptableObject.CreateInstance<FreeMarchMapDefinition>();data.bounds=new Rect(-5,-5,10,10);data.defaultTerrain=TerrainKind.Ground;data.regions=new[]{new FreeMarchMapDefinition.Region{terrain=TerrainKind.Forest,polygon=new[]{new Vector2(-1,-1),new Vector2(1,-1),new Vector2(1,1),new Vector2(-1,1)}}};map.definition=data;setup.freeMarchMap=map;
            Check(map.CanTraverse(new RoadPoint(0,0),new RoadPoint(.5,0),TerrainAccess.Forest),"forest traversal permission");Check(!map.CanTraverse(new RoadPoint(0,0),new RoadPoint(.5,0),TerrainAccess.Ground),"forest can forbid selected unit types");Check(Mathf.Abs(TerrainSpeedRules.Calculate(2,25,20)-1.2f)<.001f,"mode2 and forest reductions stack");
            var combat=ScriptableObject.CreateInstance<ArmyCombatDefinition>();combat.fullStrengthAttack=100;combat.attackRadius=1;combat.visionRadius=3;
            var a=Unit(root.transform,"A",Vector3.zero,combat);var b=Unit(root.transform,"B",Vector3.right*.5f,combat);var world=root.AddComponent<BattleWorld>();world.enabled=false;world.setup=setup;world.units=new[]{a,b};world.points=new RecoveryPoint[0];world.Initialize();
            Check(world.RequestForestHide(a),"mode3 enters forest hiding");Check(!a.ForestAttackEnabled&&!a.CanFire,"hiding defaults to no automatic fire");Check(world.IsVisible("A",a)&&!world.IsVisible("B",a),"own unit visible and enemy cannot see it");Check(world.IsVisible("A",b),"hidden army still observes enemy");world.fogEnabled=false;Check(!world.IsVisible("B",a),"hiding also applies without fog");world.fogEnabled=true;float peopleA=a.Personnel,peopleB=b.Personnel;world.Tick(.1f);Check(a.Personnel==peopleA&&b.Personnel==peopleB,"hold fire suppresses combat despite close enemy");
            Check(world.RequestForestAttack(a,true),"arm ambush without revealing");Check(a.HiddenInForest&&!world.IsVisible("B",a),"armed ambush stays invisible until firing");world.Tick(.1f);Check(b.Personnel<peopleB&&a.Personnel==peopleA,"ambush opens fire without order-dependent immediate counterfire");Check(!a.HiddenInForest&&world.IsVisible("B",a),"firing reveals hidden attacker");Check(a.State==ArmyBattleState.Engaged&&b.State==ArmyBattleState.Engaged,"ambush uses normal movement locks");Check(world.IsKnown("B",a),"combat identification preserved");Check(!world.RequestForestHide(a),"engaged unit cannot instantly hide");world.Tick(.1f);Check(a.Personnel<peopleA,"revealed attacker can receive return fire next tick");
            a.Initialize();b.Initialize();world.units=new[]{b,a};world.RequestForestHide(a);world.RequestForestAttack(a,true);peopleA=a.Personnel;world.Tick(.1f);Check(a.Personnel==peopleA&&b.Personnel<b.Capacity,"reversing unit order preserves opening ambush behavior");
            a.Initialize();b.transform.position=new Vector3(4,0);world.RequestForestHide(a);Check(world.RequestForestAttack(a,true)&&world.RequestForestAttack(a,false)&&!a.CanFire,"attack permission can be disabled again");a.transform.position=new Vector3(2,0);world.Tick(.1f);Check(!a.HiddenInForest,"leaving forest cancels hiding");Check(!world.RequestForestHide(a),"cannot hide outside forest");
            a.transform.position=Vector3.zero;world.RequestForestHide(a);setup.modes.SetMode(MouseCommandMode.RoadMarch);Check(!world.RequestForestAttack(a,true),"ambush controls require mode3");setup.modes.SetMode(MouseCommandMode.Interaction);world.currentPlayer="B";Check(!world.RequestForestHide(a)&&!world.RequestForestAttack(a,true),"cannot change enemy hiding orders");world.currentPlayer="A";Check(world.RequestForestHide(a)&&!a.HiddenInForest,"manual cancellation restores visibility");
            world.RequestForestHide(a);a.Damage(1);Check(!a.HiddenInForest,"damage reveals unit");combat.canHideInForest=false;Check(!world.RequestForestHide(a),"unit type can disable forest hiding");combat.canHideInForest=true;
            data.regions=new[]{data.regions[0],new FreeMarchMapDefinition.Region{terrain=TerrainKind.Road,polygon=new[]{new Vector2(-1,-.1f),new Vector2(1,-.1f),new Vector2(1,.1f),new Vector2(-1,.1f)}}};data.MarkDirty();Check(map.TerrainAt(new RoadPoint(0,0))==TerrainKind.Road&&map.IsForest(new RoadPoint(0,0)),"road overlay retains forest cover while retaining road terrain");
            var movement=ScriptableObject.CreateInstance<ArmyDefinition>();movement.speed=2;var mover=a.gameObject.AddComponent<ArmyRoadMover>();mover.definition=movement;var network=new RoadNetwork(new[]{new RoadPoint(-1,0),new RoadPoint(1,0)},new[]{new RoadEdge(0,1)});mover.InitializeAt(network,new RoadPoint(0,0),RoadRouteView.Create(root.transform,"test road route",.05f,3,Color.cyan));a.Initialize();Check(world.RequestForestHide(a),"hiding stops current movement");Check(!mover.CommitRoute(new[]{new RoadPoint(3,0),new RoadPoint(4,0)})&&a.HiddenInForest,"invalid movement preserves hiding");Check(mover.CommitRoute(new[]{new RoadPoint(0,0),new RoadPoint(.5,0)})&&!a.HiddenInForest,"accepted movement cancels hiding");world.RequestForestHide(a);Check(!a.Motor.IsMoving,"entering hiding clears previous route");UnityEngine.Object.DestroyImmediate(movement);
            UnityEngine.Object.DestroyImmediate(root);UnityEngine.Object.DestroyImmediate(data);UnityEngine.Object.DestroyImmediate(combat);
        }
    }
}

